import React, { useEffect, useState } from "react";
import api from "../api";
import CreateUserForm from "../pages/CreateUserForm";

interface User {
  _id: string;
  firstName: string;
  lastName: string;
  email: string;
  role: string;
  departments: string[];
  createdAt: string;
}

interface Ticket {
  _id: string;
  title: string;
  status: string;
  priority: string;
  category: string;
  createdBy: {
    firstName: string;
    lastName: string;
  };
  assignee: {
    firstName: string;
    lastName: string;
  } | null;
  createdAt: string;
}

interface Props {
  name: string;
}

const AdminDashboard: React.FC<Props> = ({ name }) => {
  const [users, setUsers] = useState<User[]>([]);
  const [tickets, setTickets] = useState<Ticket[]>([]);
  const [loadingUsers, setLoadingUsers] = useState(true);
  const [loadingTickets, setLoadingTickets] = useState(true);
  const [showCreateForm, setShowCreateForm] = useState(false);

  // ============================
  // Fetch Users
  // ============================
  const fetchUsers = async () => {
    try {
      const res = await api.get<User[]>("/admin/users");
      setUsers(res.data);
    } catch (err) {
      console.error("Failed to fetch users", err);
    } finally {
      setLoadingUsers(false);
    }
  };

  // ============================
  // Fetch Tickets
  // ============================
  const fetchTickets = async () => {
    try {
      const res = await api.get<Ticket[]>("/admin/tickets");
      setTickets(res.data);
    } catch (err) {
      console.error("Failed to fetch tickets", err);
    } finally {
      setLoadingTickets(false);
    }
  };

  // Load both on mount
  useEffect(() => {
    fetchUsers();
    fetchTickets();
  }, []);

  // ============================
  // Delete User
  // ============================
  const handleDeleteUser = async (id: string) => {
    const ok = window.confirm("Are you sure you want to delete this user?");
    if (!ok) return;

    try {
      await api.delete(`/admin/users/${id}`);
      setUsers((prev) => prev.filter((u) => u._id !== id));
    } catch (err) {
      console.error("Delete user error:", err);
      alert("Failed to delete user");
    }
  };

  return (
    <div style={{ padding: "20px" }}>
      <h2>Welcome, Admin {name}</h2>

      {/* ============================
          USER MANAGEMENT
      ============================ */}
      <h3>User Management</h3>
      <button onClick={() => setShowCreateForm(true)}>Create New User</button>

      {showCreateForm && (
        <div
          style={{
            border: "1px solid black",
            padding: "10px",
            width: "300px",
            marginTop: "10px",
          }}
        >
          <CreateUserForm
            onClose={() => setShowCreateForm(false)}
            onCreated={fetchUsers}
          />
        </div>
      )}

      {/* USERS TABLE */}
      {loadingUsers ? (
        <p>Loading users...</p>
      ) : (
        <table border={1} cellPadding={8} style={{ marginTop: "15px" }}>
          <thead>
            <tr>
              <th>Name</th>
              <th>Email</th>
              <th>Role</th>
              <th>Departments</th>
              <th>Created</th>
              <th>Actions</th>
            </tr>
          </thead>

          <tbody>
            {users.map((u) => (
              <tr key={u._id}>
                <td>
                  {u.firstName} {u.lastName}
                </td>
                <td>{u.email}</td>
                <td>{u.role}</td>
                <td>{u.departments.join(", ")}</td>
                <td>{new Date(u.createdAt).toLocaleString()}</td>
                <td>
                  <button onClick={() => handleDeleteUser(u._id)}>
                    Delete
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {/* ============================
          ALL TICKETS SECTION
      ============================ */}
      <h3 style={{ marginTop: "40px" }}>All Tickets</h3>

      {loadingTickets ? (
        <p>Loading tickets...</p>
      ) : (
        <table border={1} cellPadding={8} style={{ marginTop: "15px" }}>
          <thead>
            <tr>
              <th>Title</th>
              <th>Status</th>
              <th>Priority</th>
              <th>Category</th>
              <th>Created By</th>
              <th>Assignee</th>
              <th>Created</th>
            </tr>
          </thead>

          <tbody>
            {tickets.map((t) => (
              <tr key={t._id}>
                <td>{t.title}</td>
                <td>{t.status}</td>
                <td>{t.priority}</td>
                <td>{t.category}</td>
                <td>
                  {t.createdBy.firstName} {t.createdBy.lastName}
                </td>
                <td>
                  {t.assignee
                    ? `${t.assignee.firstName} ${t.assignee.lastName}`
                    : "-"}
                </td>
                <td>{new Date(t.createdAt).toLocaleString()}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      <button
        onClick={() => {
          document.cookie =
            "token=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;";
          window.location.reload();
        }}
        style={{ marginTop: "20px" }}
      >
        Logout
      </button>
    </div>
  );
};

export default AdminDashboard;
